/// A closed interval [min, max] with `min < max`.
#[derive(Debug, Clone, PartialEq)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    /// Constructs a new `Interval`. Panics if `min >= max`.
    pub fn new(min: f64, max: f64) -> Self {
        assert!(
            min < max,
            "Interval::new called with min >= max: {} >= {}",
            min,
            max
        );
        Interval { min, max }
    }
}

/// A descriptor for a Chebyshev polynomial.
/// 
/// - `coefficients` are in increasing degree order (T₀, T₁, T₂, ...).
/// - `domain` is the interval over which the polynomial is defined (default [-1, 1]).
/// - `window` is the interval to map polynomial values into (default [-1, 1]).
#[derive(Debug, Clone, PartialEq)]
pub struct ChebyshevPoly {
    pub coefficients: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Constructs a Chebyshev polynomial descriptor from a non-empty list of i8 coefficients.
///
/// The input coefficients are interpreted in increasing degree order, and are
/// converted to i32. The domain and window are both set to [-1, 1].
///
/// # Panics
///
/// Panics if `coef` is empty.
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    assert!(
        !coef.is_empty(),
        "Chebyshev polynomial must have at least one coefficient"
    );

    // Convert coefficients to i32, preserving order.
    let coefficients: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Default domain and window: [-1, 1]
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coefficients,
        domain,
        window,
    }
}

